/**
 * 预设工作区组件导出
 */

// 主组件
export { PresetWorkspace } from "./PresetWorkspace";

// 上下文
export { useWorkspace } from "./context";
export type { WorkspaceContextValue } from "./context";

// 工具栏
export { PresetWorkspaceToolbar } from "./PresetWorkspaceToolbar";

// Hooks
export { useWorkspaceState } from "./hooks/useWorkspaceState";
export type {
  EditingBlockInfo,
  PanelState,
  WorkspaceActions,
  WorkspaceState,
} from "./hooks/useWorkspaceState";

/**
 * Yjs/IndexedDB 错误处理组件
 */

import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogFooter } from "@/components/ui/dialog";
import { color, colorAlpha } from "@/styles/tokens";
import { AlertTriangle, Database, RefreshCw } from "lucide-react";

export type StorageErrorType =
  | "indexeddb-not-supported"
  | "indexeddb-blocked"
  | "indexeddb-quota-exceeded"
  | "indexeddb-unknown";

interface StorageErrorInfo {
  type: StorageErrorType;
  title: string;
  description: string;
  suggestion: string;
  canRetry: boolean;
}

const ERROR_INFO: Record<StorageErrorType, Omit<StorageErrorInfo, "type">> = {
  "indexeddb-not-supported": {
    title: "浏览器不支持本地存储",
    description:
      "你的浏览器不支持 IndexedDB，无法保存游戏进度。这可能是因为浏览器版本过旧或处于隐私模式。",
    suggestion:
      "请使用 Chrome 89+ / Firefox 111+ / Safari 15.2+ / Edge 89+ 等现代浏览器，并确保未处于隐私/无痕模式。",
    canRetry: false,
  },
  "indexeddb-blocked": {
    title: "存储访问被阻止",
    description:
      "浏览器阻止了对本地存储的访问。这可能是因为隐私设置、浏览器扩展或企业策略。",
    suggestion:
      "请检查浏览器设置，确保允许网站使用本地存储。如果使用了隐私扩展，请将本站加入白名单。",
    canRetry: true,
  },
  "indexeddb-quota-exceeded": {
    title: "存储空间不足",
    description: "本地存储空间已满，无法保存更多数据。",
    suggestion: "请清理浏览器缓存或删除不需要的存档，释放存储空间后重试。",
    canRetry: true,
  },
  "indexeddb-unknown": {
    title: "存储初始化失败",
    description: "初始化本地存储时发生未知错误。",
    suggestion: "请刷新页面重试。如果问题持续，请尝试清除浏览器缓存。",
    canRetry: true,
  },
};

interface StorageErrorDialogProps {
  open: boolean;
  errorType: StorageErrorType;
  onRetry?: () => void;
  onDismiss?: () => void;
}

/**
 * 存储错误对话框
 */
export function StorageErrorDialog({
  open,
  errorType,
  onRetry,
  onDismiss,
}: StorageErrorDialogProps) {
  const info = ERROR_INFO[errorType];

  return (
    <Dialog open={open} onOpenChange={() => onDismiss?.()}>
      <DialogContent title={info.title} className="max-w-md">
        {/* 图标 */}
        <div className="flex justify-center mb-4">
          <div
            className="p-4 rounded-full"
            style={{
              background: colorAlpha("error", 0.15),
            }}
          >
            {errorType === "indexeddb-quota-exceeded" ? (
              <Database
                className="w-12 h-12"
                style={{ color: color("error") }}
              />
            ) : (
              <AlertTriangle
                className="w-12 h-12"
                style={{ color: color("error") }}
              />
            )}
          </div>
        </div>

        {/* 描述 */}
        <p
          className="text-center mb-4"
          style={{ color: color("textSecondary") }}
        >
          {info.description}
        </p>

        {/* 建议 */}
        <div
          className="p-3 rounded-lg mb-4"
          style={{
            background: colorAlpha("warning", 0.1),
            border: `1px solid ${colorAlpha("warning", 0.3)}`,
          }}
        >
          <p className="text-sm" style={{ color: color("warning") }}>
            提示：{info.suggestion}
          </p>
        </div>

        {/* 操作按钮 */}
        <DialogFooter>
          {info.canRetry && onRetry && (
            <Button onClick={onRetry} variant="default">
              <RefreshCw className="w-4 h-4 mr-2" />
              重试
            </Button>
          )}
          {onDismiss && (
            <Button onClick={onDismiss} variant="ghost">
              {info.canRetry ? "取消" : "我知道了"}
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * 检测 IndexedDB 错误类型
 */
export function detectStorageErrorType(error: unknown): StorageErrorType {
  if (error instanceof Error) {
    const message = error.message.toLowerCase();
    const name = error.name.toLowerCase();

    // 配额超限
    if (
      name === "quotaexceedederror" ||
      message.includes("quota") ||
      message.includes("storage")
    ) {
      return "indexeddb-quota-exceeded";
    }

    // 访问被阻止
    if (
      name === "securityerror" ||
      message.includes("blocked") ||
      message.includes("denied") ||
      message.includes("security")
    ) {
      return "indexeddb-blocked";
    }
  }

  return "indexeddb-unknown";
}

/**
 * 检测 IndexedDB 是否真正可用（不仅仅是 API 存在）
 * 返回 null 表示可用，否则返回错误类型
 */
export async function checkIndexedDBAvailability(): Promise<StorageErrorType | null> {
  // 1. 检查 API 是否存在
  if (typeof indexedDB === "undefined") {
    return "indexeddb-not-supported";
  }

  // 2. 尝试打开一个测试数据库
  try {
    const testDbName = "__lyra_idb_test__";

    await new Promise<void>((resolve, reject) => {
      const request = indexedDB.open(testDbName, 1);

      request.onerror = () => {
        reject(request.error);
      };

      request.onsuccess = () => {
        // 成功打开，关闭并删除测试数据库
        request.result.close();
        const deleteRequest = indexedDB.deleteDatabase(testDbName);
        deleteRequest.onsuccess = () => resolve();
        deleteRequest.onerror = () => resolve(); // 删除失败也算成功
      };

      request.onblocked = () => {
        reject(new Error("IndexedDB blocked"));
      };
    });

    return null; // 可用
  } catch (error) {
    return detectStorageErrorType(error);
  }
}

import "@/styles/globals.css";
import { enableMapSet } from "immer";
import React, { useState } from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import {
  initYjs,
  showIndexedDBError,
  StorageErrorDialog,
  yjsManager,
  type StorageErrorType,
} from "./core/yjs";
import { usePresetStore } from "./lib/prompt";
import { registerAllModules } from "./modules";

// 启用 Immer 的 Map/Set 支持
enableMapSet();

/**
 * 错误页面组件
 * 当 Yjs 初始化失败时显示
 */
function ErrorPage({
  errorType,
  onRetry,
}: {
  errorType: StorageErrorType;
  onRetry: () => void;
}) {
  const [open, setOpen] = useState(true);

  return (
    <div className="dark min-h-screen bg-black flex items-center justify-center">
      <StorageErrorDialog
        open={open}
        errorType={errorType}
        onRetry={onRetry}
        onDismiss={() => setOpen(false)}
      />
      {/* 背景提示 */}
      {!open && (
        <div className="text-center text-gray-500">
          <p className="text-lg mb-4">游戏无法启动</p>
          <button
            onClick={() => setOpen(true)}
            className="text-cyan-400 hover:text-cyan-300 underline"
          >
            查看详情
          </button>
        </div>
      )}
    </div>
  );
}

/**
 * 渲染错误页面
 */
function renderErrorPage(errorType: StorageErrorType, onRetry: () => void) {
  const root = document.getElementById("root");
  if (!root) return;

  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <ErrorPage errorType={errorType} onRetry={onRetry} />
    </React.StrictMode>
  );
}

/**
 * 渲染主应用
 */
function renderApp() {
  const root = document.getElementById("root");
  if (!root) return;

  ReactDOM.createRoot(root).render(
    <React.StrictMode>
      <App />
    </React.StrictMode>
  );
}

// 初始化应用
async function bootstrap() {
  // 1. 初始化 Yjs（包含 IndexedDB 可用性检查）
  const initResult = await initYjs();

  if (!initResult.success) {
    // 尝试使用 React 渲染错误页面
    try {
      renderErrorPage(initResult.errorType!, () => {
        // 重试：刷新页面
        window.location.reload();
      });
    } catch {
      // 降级：使用 alert
      showIndexedDBError(initResult.errorType);
    }
    return;
  }

  // 2. 挂载全局 API（方便控制台测试）
  if (typeof window !== "undefined") {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    (window as any).yjsManager = yjsManager;
  }

  // 3. 注册所有模块（命令处理器、事件处理器等）
  await registerAllModules();

  // 4. 初始化预设系统
  try {
    await usePresetStore.getState().loadPresets();
  } catch (error) {
    console.error("[Bootstrap] Failed to initialize preset store:", error);
    // 预设加载失败不阻塞应用启动，会在使用时提示用户
  }

  // 5. 渲染应用
  renderApp();
}

bootstrap().catch(() => {
  // Bootstrap failed silently
});
